beginning.embedded_functions:
//each function name should be prefixed by em_
/**
* This function checks if the NGSetupRequest message count exceeds a threshold within a short time window.
* @param packet_count The number of NGSetupRequest messages received.
* @param time_window_ms The time window in milliseconds.
* @return 1 if the packet count exceeds the threshold, 0 otherwise.
*/
static inline int em_check_ngsetup_storm(uint32_t packet_count, uint32_t time_window_ms) {
  // Define a threshold for the number of NGSetupRequest messages
  uint32_t threshold = 5; 

  if (packet_count > threshold) {
    return 1;
  } else {
    return 0;
  }
}
